package ai.eva.android.probe;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import org.json.*;import java.net.*;import java.io.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;

/** Provider metadata and Keystore-encrypted credentials. Never exposes keys to WebView. */
public final class ModelStore {
 final Context context;static final Object LOCK=new Object();
 ModelStore(Context c){context=c.getApplicationContext();}
 android.content.SharedPreferences prefs(){return context.getSharedPreferences("eva-providers",0);}
 JSONObject read()throws Exception{return new JSONObject(prefs().getString("config","{\"providers\":[],\"active\":\"\"}"));}
 JSONObject provider(String id)throws Exception{JSONArray a=read().getJSONArray("providers");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id))return a.getJSONObject(i);throw new IOException("提供商不存在，请重新选择");}
 JSONObject publicConfig()throws Exception{JSONObject config=read();JSONArray a=config.getJSONArray("providers");for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);p.put("hasKey",!p.optString("secret").isEmpty());p.remove("secret");}android.content.SharedPreferences account=context.getSharedPreferences("eva-account",0);config.put("account",new JSONObject().put("loggedIn",account.getBoolean("loggedIn",false)).put("preferred",account.getBoolean("preferred",false)).put("model",account.getString("model","")).put("effort",account.getString("effort","")).put("serviceTier",account.getString("serviceTier","")));return config;}
 static String baseUrl(String input)throws Exception{String value=input.trim();if(value.length()>2048)throw new IOException("服务地址过长");URI uri=new URI(value);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null)throw new IOException("请输入不含账号、查询参数或片段的 HTTPS API 地址");while(value.endsWith("/"))value=value.substring(0,value.length()-1);if(value.endsWith("/responses")||value.endsWith("/models"))throw new IOException("请填写 API 基础地址，例如 https://服务域名/v1");return value;}
 static String field(String s,String label,int max)throws IOException{s=s.trim();if(s.isEmpty()||s.length()>max||s.indexOf('\n')>=0||s.indexOf('\r')>=0)throw new IOException(label+"为空、过长或包含换行");return s;}
 javax.crypto.SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);String alias="eva-provider-credentials-v1";if(!ks.containsAlias(alias)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)ks.getKey(alias,null);}
 String encrypt(String value)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());return Base64.encodeToString(c.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(c.doFinal(value.getBytes("UTF-8")),Base64.NO_WRAP);}
 String secret(JSONObject p)throws Exception{String[] parts=p.getString("secret").split(":",2);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new String(c.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),"UTF-8");}
 String save(String id,String name,String url,String model,String secret)throws Exception{synchronized(LOCK){JSONObject config=read();JSONArray a=config.getJSONArray("providers");JSONObject prior=null;for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id))prior=a.getJSONObject(i);if(prior==null){if(a.length()>=20)throw new IOException("最多保存 20 个提供商");id=java.util.UUID.randomUUID().toString();}
  JSONObject p=new JSONObject().put("id",id).put("name",field(name,"名称",80)).put("url",baseUrl(url)).put("model",(model.trim().isEmpty()?"":field(model,"模型 ID",200)));
  if(secret.trim().isEmpty()){if(prior==null||!prior.optString("url").equals(p.getString("url")))throw new IOException("新增或更换服务地址时，请填写 API Key");p.put("secret",prior.getString("secret"));}else p.put("secret",encrypt(field(secret,"API Key",8192)));
  boolean replaced=false;for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id)){a.put(i,p);replaced=true;}if(!replaced)a.put(p);if(config.optString("active").isEmpty())config.put("active",id);if(!prefs().edit().putString("config",config.toString()).commit())throw new IOException("保存失败");return id;}}
 void select(String id)throws Exception{synchronized(LOCK){field(provider(id).optString("model"),"模型 ID",200);JSONObject c=read();c.put("active",id);context.getSharedPreferences("eva-account",0).edit().putBoolean("preferred",false).commit();if(!prefs().edit().putString("config",c.toString()).commit())throw new IOException("保存失败");}}
 void delete(String id)throws Exception{synchronized(LOCK){JSONObject c=read();JSONArray old=c.getJSONArray("providers"),next=new JSONArray();for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).getString("id").equals(id))next.put(old.get(i));c.put("providers",next);if(c.optString("active").equals(id))c.put("active",next.length()>0?next.getJSONObject(0).getString("id"):"");if(!prefs().edit().putString("config",c.toString()).commit())throw new IOException("删除失败");}}
}
